/* Swiggy-style home additions */
.search{display:flex;align-items:center;gap:8px;padding:12px 14px;border-radius:var(--ds-radius-md);border:1px solid var(--ps-border);background:var(--ps-surface);margin-bottom:12px}
.search i{font-style:normal;opacity:.7}
.search input{flex:1;border:none;background:none;color:inherit;font-size:14px;outline:none}
.offerSheet{position:sticky;top:8px;z-index:5;display:flex;justify-content:space-between;align-items:flex-start;gap:10px;padding:14px 16px;border-radius:var(--ds-radius-md);background:linear-gradient(120deg,var(--ds-primary-500),var(--ds-primary-400));color:var(--ds-on-primary);border:1px solid var(--ds-accent-500);box-shadow:0 10px 24px color-mix(in srgb,var(--ds-primary-500) 40%,transparent);margin-bottom:12px}
.offerSheet span{font-size:10px;letter-spacing:1px;color:var(--ds-accent-500)}
.offerSheet h3{margin:4px 0 2px;letter-spacing:2px}
.offerSheet p{margin:0;font-size:12px;opacity:.9}
.offerSheet button{background:none;border:none;color:var(--ds-on-primary);font-size:16px;cursor:pointer}
.offerStrip{display:grid;gap:8px;padding:14px;border-radius:var(--ds-radius-md);border:1px dashed var(--ds-accent-500);background:var(--ps-surface);margin-bottom:4px}
.offerStrip>b{font-size:10px;letter-spacing:1px;color:var(--ds-accent-500)}
.offerStrip>div{display:flex;gap:8px;overflow-x:auto;padding-bottom:4px}
.offerStrip article{min-width:170px;display:grid;gap:2px;padding:10px 12px;border-radius:var(--ds-radius-md);border:1px solid var(--ps-border);background:var(--ps-bg,color-mix(in srgb,var(--ds-shadow-ink) 15%,transparent))}
.offerStrip article strong{letter-spacing:1px}
.offerStrip article small{font-size:11px;opacity:.85}
.offerStrip article em{font-style:normal;font-size:9px;font-weight:800;justify-self:start;padding:2px 8px;border-radius:var(--ds-radius-sm);background:var(--ds-accent-500);color:var(--paw-link)}
.offerStrip>small{font-size:10px;opacity:.7}

/* ============================================================================
   READABILITY & REAL-PHONE FIT PASS (founder: fonts too small, layout cluttered,
   fit-to-screen broken on actual phones). Same class names re-declared later in
   the file so they win the cascade; the desktop phone-frame mock scales with it.
   Floor: no text below 9px; controls 11px+; inputs 16px (blocks iOS focus zoom).
   ========================================================================== */
.phone>header small{font-size:10px}.phone>header b{font-size:13px}
.title small{font-size:10px;letter-spacing:1.4px}.title h2{font-size:26px}
.phone>nav{height:76px;padding:8px 8px calc(12px + env(safe-area-inset-bottom,0px))}
.phone>nav button{font-size:10px;gap:3px}.phone>nav i{font-size:21px}
.screen{padding-bottom:calc(118px + env(safe-area-inset-bottom,0px))}
.hero span,.offer span{font-size:10px}.hero p,.offer p{font-size:12px;line-height:1.55}
.hero button,.offer button,.reminder button{font-size:12px;padding:10px 14px;border-radius:var(--ds-radius-md)}
.head{margin:22px 2px 11px}.head h3{font-size:17px}.head button{font-size:11px}
.services{gap:12px 8px}
.services button{font-size:11px;font-weight:700;gap:7px;line-height:1.25}
.services i{width:56px;height:56px;border-radius:var(--ds-radius-lg);font-size:24px;box-shadow:0 2px 8px color-mix(in srgb,var(--ds-shadow-ink) 6%,transparent)}
.next strong{font-size:12px}.next span{font-size:10px}.next div small{font-size:9px}
.next>b{width:50px;height:54px;font-size:19px}.next>b small{font-size:9px;margin-top:-4px}
.reminder b{font-size:12px}.reminder span{font-size:10px}
.offer h3{font-size:18px}
.steps>span{font-size:10px}
.petCards span{font-size:11px}
.packs span{font-size:9px}.packs p{font-size:11px;line-height:1.5}
.add,.primary{font-size:13px;padding:14px;border-radius:var(--ds-radius-md)}
