              </span>
            )}
            {mode !== "boarding" && <span>
              PawSpace protection & 24/7 support<b>{money(protection)}</b>
            </span>}
            {false && taxi && mode === "boarding" && (
              <span>
                Tracked Pet Taxi<b>{money(taxiFee)}</b>
              </span>
            )}
            {currentMeeting&&<p>Introduction {currentMeeting.id} is a separate request and is excluded from this stay total.</p>}
            {mode === "boarding" && selectedBenefits.length > 0 && <p>{hostRequestsExcludedNote(selectedBenefits)}</p>}
            <strong>
              Booking total<b>{quoteMoney(total)}</b>
            </strong>
          </div>
          {routeScope==="v2"&&<TestCoinServicePreview serviceName={mode==="boarding"?"Boarding":"Pet Sitting"} customerId={customer.customerId} eligibleAmount={activeQuote?.totalAmount??null} actualPayable={activeQuote?.amountDueNow??null}/>}
          {splitEligible ? (
            <section className={styles.paymentChoice}>
              <header>
                <div>
                  <span>LONG-STAY PAYMENT</span>
                  <b>{nights} nights qualifies for partial payment</b>
                </div>
                <em>MORE THAN 4 NIGHTS</em>
              </header>
              <button
                className={splitPayment ? styles.selected : ""}
                onClick={() => setSplitPayment(true)}
              >
                <i>{splitPayment ? "✓" : ""}</i>
                <span>
                  <b>Reserve with 50% now</b>
                  <small>
                    {quoteMoney(Math.round(total*50)/100)} now · {quoteMoney(Math.round((total-Math.round(total*50)/100)*100)/100)} due 24
                    hours before check-in
                  </small>
                </span>
              </button>
              <button
                className={!splitPayment ? styles.selected : ""}
                onClick={() => setSplitPayment(false)}
              >
                <i>{!splitPayment ? "✓" : ""}</i>
                <span>
                  <b>Pay the full amount now</b>
                  <small>{quoteMoney(total)} · no later balance</small>
                </span>
              </button>

            </section>
          ) : (
            <article className={styles.fullPaymentNote}>
              <i>₹</i>
              <div>
                <b>{mode === "boarding" ? "Full payment for daycare and stays up to 4 nights" : "Full payment for a Home Visit or stays up to 4 nights"}</b>
                <span>
                  {"50/50 split payment becomes available automatically for overnight stays longer than four nights."}
                </span>
              </div>
            </article>
          )}
          <p className={styles.hint}>Coupons can&apos;t be used for {mode === "boarding" ? "Boarding" : "Pet Sitting"} yet.</p>
          <article className={styles.protection}>
            <i>✓</i>
            <div>
              <b>PawSpace Stay Protection</b>
              <span>{mode === "boarding" ? "Host capacity is rechecked when requested. Payment is not yet verified. Cancellation/refund policy, live messaging and 24/7 support integrations remain pre-live gates." : "Your price is ready. Your sitter's availability is confirmed when you send this request; payment is a sandbox test payment."}</span>
            </div>
          </article>
          <p className={styles.hint}>After payment you can still update feeding, medication and other instructions from Activity. Vet and emergency contacts{mode === "sitting" ? " and home access" : ""} stay required until the service begins.</p>
          <label className={styles.consent}>
            <input
              type="checkbox"
              checked={agreed}
              onChange={(e) => setAgreed(e.target.checked)}
            />{" "}
            I agree to care, home-access, cancellation, media and emergency
            terms.
          </label>
          <p className={styles.hint}>
            {mode === "boarding" ? "Production OTP is not connected; this UAT checkout uses a sandbox payment." : "This checkout uses your signed-in customer account and a sandbox payment."} {activeQuote && `${money(reserveAmount)} will be collected in this test checkout.`} {!activeQuote ? "The payment schedule will appear when pricing is ready." : balanceAmount > 0
              ? `${quoteMoney(balanceAmount)} is due 24 hours before the booking starts.`
              : "No later balance remains."}
          </p>
          <button className={styles.back} disabled={scheduling} onClick={() => setStage(3)}>
            ← Care plan
          </button>
          <button
            disabled={!agreed || !datesValid || scheduling || selectedPets.length === 0 || !serviceLocation || !activeQuote}
            className={styles.primary}
            onClick={confirm}
          >
            {scheduling ? "Locking care capacity…" : !activeQuote ? (quoteError ? "Price unavailable" : "Calculating price…") : "Book stay"}
          </button>
          {scheduleError && <p role="alert">{scheduleError}</p>}
          {scheduleDiagnosis && <details className={styles.diagnosis} open data-testid="stay-reservation-diagnosis">
            <summary>What to do next</summary>
            <p>{scheduleDiagnosis.headline}</p>
            <p>{scheduleDiagnosis.action}</p>
            <p>Reference for support: <code>{scheduleDiagnosis.code}</code>. Nothing has been charged.</p>
            {scheduleDiagnosis.goTo === "caregiver" && <button type="button" onClick={() => {setSitterWindowKey("");setBoardingHostWindowKey("");setHostRetry((value) => value + 1);setStage(2);}}>Search caregivers again</button>}
            {(scheduleDiagnosis.goTo === "plan" || scheduleDiagnosis.goTo === "address") && <button type="button" onClick={() => setStage(1)}>Back to Plan</button>}
          </details>}
        </>
      )}
    </section>
  );
}

function Head({ title, note }: { title: string; note: string }) {
  return (
    <div className={styles.head}>
      <h3>{title}</h3>
      <small>{note}</small>
    </div>
  );
}
function LiveStay({bookingId,mode,caregiver,view,setView,initialCarePlan,initialError,start,end,routeScope="legacy"}:{routeScope?:"legacy"|"v2";bookingId:string;initialCarePlan?:SittingCarePlan;initialError?:string;start:string;end:string;nights:number;mode:Mode;caregiver:Caregiver;pets:string[];total:number;taxi:boolean;view:View;setView:(value:View)=>void;flash:(message:string)=>void}){
 const introduction=caregiver.providerId?<StayMeetingRequest key={`${mode}:${caregiver.providerId}:${start}:${end}`} providerId={caregiver.providerId} providerName={caregiver.name} serviceCode={mode==="boarding"?"boarding":"pet_sitting"} start={start} end={end} onRequested={onSavedStayIntroduction}/>:null;
 if(mode === "sitting")return <><SittingCustomerPanel key={bookingId} bookingId={bookingId} routeScope={routeScope} initialCarePlan={initialCarePlan} initialError={initialError}/>{introduction}</>;
 return <section className={styles.flow}><h2>Boarding booking · {bookingId}</h2><Link href={`${routeScope==="v2"?"/v2":""}/boarding/manage?bookingId=${encodeURIComponent(bookingId)}`}>Open saved booking and care</Link><Link href={routeScope==="v2"?`/v2/taxi?sourceBookingId=${encodeURIComponent(bookingId)}`:`/mobile-app?service=pet_taxi&sourceBookingId=${encodeURIComponent(bookingId)}`}>Add Pet Taxi for this Boarding stay →</Link><nav aria-label="Boarding booking sections" className={styles.liveTabs}><button onClick={()=>setView("stay")}>Stay status</button><button onClick={()=>setView("care")}>Care and requests</button></nav>{view === "stay"?<BoardingCustomerStayStatus bookingId={bookingId} caregiverName={caregiver.name}/>:<BoardingCustomerStayPanel routeScope={routeScope} bookingId={bookingId} caregiverName={caregiver.name} initialCarePlan={initialCarePlan} initialError={initialError}/> }{view === "care" && introduction}</section>;
}

export type ThemeId="emerald"|"signature"|"coral"|"midnight"|"sage"|"rose"|"ocean";
export type AppearanceMode="system"|"light"|"dark";
export type ThemeOption={id:ThemeId;label:string;tagline:string;swatches:[string,string,string]};
export const THEME_STORAGE_KEY="pawspace.customer.theme";
export const APPEARANCE_STORAGE_KEY="pawspace.customer.appearance";
export const PLATFORM_THEME_STORAGE_KEY="pawspace.platform.default-theme";
/** Device-local colour choices, independent of Professional/Fun styling. */
export const themes:ThemeOption[]=[
{id:"emerald",label:"Emerald + Gold",tagline:"Calm greens, warm gold and ivory",swatches:["#01261F","#E6B34E","#FFF8EE"]},
{id:"signature",label:"Brand Purple + Gold",tagline:"PawSpace purple, golden accents and soft lavender",swatches:["#894AED","#FFAF00","#F7F3FF"]},
{id:"coral",label:"Coral + Gold",tagline:"Warm coral, golden sunshine and peach cream",swatches:["#B94339","#FFAF00","#FFF5EF"]},
];
const allThemeIds=new Set<ThemeId>(["emerald","signature","coral","midnight","sage","rose","ocean"]);
const offeredThemeIds=new Set<ThemeId>(["emerald","signature","coral"]);
const appearanceModes=new Set<AppearanceMode>(["system","light","dark"]);
export function isThemeId(value:string|null|undefined):value is ThemeId{return Boolean(value&&allThemeIds.has(value as ThemeId));}
export function isOfferedTheme(value:string|null|undefined):value is ThemeId{return value==="emerald"||value==="signature"||value==="coral";}
export function isAppearanceMode(value:string|null|undefined):value is AppearanceMode{return Boolean(value&&appearanceModes.has(value as AppearanceMode));}
export function resolveBrandTheme(value:string|null|undefined):ThemeId{
  if(value==="coral")return "coral";
  if(value==="signature")return "signature";
  if(value==="emerald")return "emerald";
  return "emerald";
}
export function readPlatformDefaultTheme():ThemeId{
  try{
    if(typeof localStorage!=="undefined"){
      const stored=localStorage.getItem(PLATFORM_THEME_STORAGE_KEY);
      if(isOfferedTheme(stored))return stored;
    }
  }catch{ /* Device-only default. */ }
  const configuredTheme=typeof process!=="undefined"?process.env.NEXT_PUBLIC_PAWSPACE_DEFAULT_THEME:undefined;
  return isOfferedTheme(configuredTheme)?configuredTheme:"emerald";
}
const configuredTheme=typeof process!=="undefined"?process.env.NEXT_PUBLIC_PAWSPACE_DEFAULT_THEME:undefined;
const configuredAppearance=typeof process!=="undefined"?process.env.NEXT_PUBLIC_PAWSPACE_DEFAULT_APPEARANCE:undefined;
export const DEFAULT_THEME:ThemeId=isOfferedTheme(configuredTheme)?configuredTheme:"emerald";
export const DEFAULT_APPEARANCE:AppearanceMode=isAppearanceMode(configuredAppearance)?configuredAppearance:"system";
export const OFFERED_THEME_IDS=offeredThemeIds;

export type VisualStyle = "professional" | "cartoon";
export const STYLE_STORAGE_KEY = "pawspace.visual-style";
export const DEFAULT_STYLE: VisualStyle = "professional";
export function resolveVisualStyle(value: string | null): VisualStyle { return value === "cartoon" ? "cartoon" : DEFAULT_STYLE; }
/* Approved appearance model (native design handoff, 3 Oct 2026): one shared layout, two theme identities.
   "editorial" = Editorial Sanctuary (A), the default and safe fallback. "concierge" = Modern Concierge (C), offered only
   after its release gate passes. Legacy palette and Professional/Fun values are migration metadata only and never render. */
export type ThemeId="editorial"|"concierge";
export type LegacyThemeId="emerald"|"signature"|"coral"|"midnight"|"sage"|"rose"|"ocean";
export type AppearanceMode="system"|"light"|"dark";
export type ThemeOption={id:ThemeId;label:string;tagline:string;swatches:[string,string,string];availableAfterValidation?:true};
/* Legacy device keys. Read once for migration into the appearance record; they no longer decide the rendered theme. */
export const THEME_STORAGE_KEY="pawspace.customer.theme";
export const APPEARANCE_STORAGE_KEY="pawspace.customer.appearance";
export const PLATFORM_THEME_STORAGE_KEY="pawspace.platform.default-theme";
/** The two approved appearance names. Concierge stays listed so the control can show it as not yet available. */
export const themes:ThemeOption[]=[
{id:"editorial",label:"Editorial Sanctuary",tagline:"Forest green, warm ivory and calm editorial type",swatches:["#164A3D","#C46E4D","#F6F3EC"]},
{id:"concierge",label:"Modern Concierge",tagline:"Cobalt, citrus and crisp white",swatches:["#174DC8","#D8EA65","#EDF2FA"],availableAfterValidation:true},
];
const themeIds=new Set<ThemeId>(["editorial","concierge"]);
const legacyThemeIds=new Set<LegacyThemeId>(["emerald","signature","coral","midnight","sage","rose","ocean"]);
const appearanceModes=new Set<AppearanceMode>(["system","light","dark"]);
export const SAFE_THEME:ThemeId="editorial";
/** C release gate. Closed unless the build sets NEXT_PUBLIC_PAWSPACE_CONCIERGE_AVAILABLE=true after every required acceptance case passes. */
export function isConciergeAvailable(flag:string|undefined=typeof process!=="undefined"?process.env.NEXT_PUBLIC_PAWSPACE_CONCIERGE_AVAILABLE:undefined):boolean{return flag==="true";}
export const CONCIERGE_AVAILABLE=isConciergeAvailable();
export function isThemeId(value:string|null|undefined):value is ThemeId{return Boolean(value&&themeIds.has(value as ThemeId));}
export function isLegacyThemeId(value:string|null|undefined):value is LegacyThemeId{return Boolean(value&&legacyThemeIds.has(value as LegacyThemeId));}
/** A theme that may render right now: editorial always, concierge only while its gate is open. */
export function isOfferedTheme(value:string|null|undefined,conciergeAvailable:boolean=CONCIERGE_AVAILABLE):value is ThemeId{return value==="editorial"||(value==="concierge"&&conciergeAvailable);}
export function isAppearanceMode(value:string|null|undefined):value is AppearanceMode{return Boolean(value&&appearanceModes.has(value as AppearanceMode));}
/** Effective theme for any stored or submitted value: a gated or unknown value renders the safe theme without being rewritten. */
export function resolveBrandTheme(value:string|null|undefined,conciergeAvailable:boolean=CONCIERGE_AVAILABLE):ThemeId{
  if(isOfferedTheme(value,conciergeAvailable))return value;
  return SAFE_THEME;
}
/** New-user default supplied by the build (NEXT_PUBLIC_PAWSPACE_DEFAULT_THEME). Only A, or C while its gate is open, is accepted. */
export function readPlatformDefaultTheme():ThemeId{
  const configuredTheme=typeof process!=="undefined"?process.env.NEXT_PUBLIC_PAWSPACE_DEFAULT_THEME:undefined;
  return isOfferedTheme(configuredTheme)?configuredTheme:SAFE_THEME;
}
const configuredAppearance=typeof process!=="undefined"?process.env.NEXT_PUBLIC_PAWSPACE_DEFAULT_APPEARANCE:undefined;
export const DEFAULT_THEME:ThemeId=readPlatformDefaultTheme();
export const DEFAULT_APPEARANCE:AppearanceMode=isAppearanceMode(configuredAppearance)?configuredAppearance:"system";
export const OFFERED_THEME_IDS:ReadonlySet<ThemeId>=new Set<ThemeId>(CONCIERGE_AVAILABLE?["editorial","concierge"]:["editorial"]);

/* Professional/Fun no longer selects a layout. The shared layout always renders the professional structure; a stored
   "cartoon" value is kept only as inactive migration metadata. */
export type VisualStyle = "professional" | "cartoon";
export const STYLE_STORAGE_KEY = "pawspace.visual-style";
export const DEFAULT_STYLE: VisualStyle = "professional";
export function resolveVisualStyle(value: string | null): VisualStyle { return value === "cartoon" ? "cartoon" : DEFAULT_STYLE; }

