 if(recoveryBookingId)return <main className={styles.shell}><section className={styles.card} aria-label="Existing training booking"><h1>Your Training booking is saved</h1><p>{recoveryBookingId}</p><p>Resume the same booking to check its reserved sessions and payment. This page will not create another booking.</p><Link href={bookingRecordHref(recoveryBookingId)}>View booking &amp; payment →</Link><p><Link href={pathname}>Start a separate booking</Link></p></section></main>;
 return <main className={styles.shell}><header><Link href={href("/")}>PawSpace</Link><p>{routeScope==="v2"?"DOG TRAINING":"DOG TRAINING · CANONICAL UAT"}</p><h1>{routeScope==="v2"?"Choose the right training programme":"Choose a server-owned Training programme"}</h1><p>{routeScope==="v2"?"Pick your dogs, a plan and a time. Prices and trainer availability are checked live for every session.":"Catalogue, price, trainer eligibility and schedule are read from PawSpace governance. The browser no longer invents a plan, trainer or progress journey."}</p></header>{routeScope==="v2"&&recoveryBookingId&&<section className={styles.card} aria-label="Existing training booking"><p>Already reserved a programme? Your booking, its payment status and Manage link are on its own page.</p><div className={styles.actions}><Link href={bookingRecordHref(recoveryBookingId)}>View booking & payment →</Link></div></section>}{error&&<p role="alert">{error}</p>}<section className={styles.card}><h2>1. Pet and first session</h2><div className={styles.grid2}><div role="group" aria-labelledby="training-dogs-label"><span id="training-dogs-label">Dogs</span>{accountLoading?<p>Loading your pets…</p>:accountError?<p role="alert">{accountError} <Link href={href("/mobile-app")}>Sign in →</Link></p>:dogs.length===0?<p>No dogs on your profile yet. <Link href={href("/mobile-app")}>Add one in My PawSpace →</Link></p>:<div className={styles.petList}>{dogs.map(pet=><button key={pet.id} type="button" onClick={()=>togglePet(pet.id)} aria-pressed={selectedPetIds.includes(pet.id)} className={styles.choice}><strong>{pet.name}</strong><small className={styles.block}>{petLabel(pet)}</small></button>)}<small>{petCount} {petCount===1?"dog":"dogs"} selected{account?` · booking as ${account.name}`:""}</small>{packageCode!=="trainer-meet-greet"&&selectedPets.some(pet=>!isVaccinatedStatus(pet.vaccinationStatus))&&<p role="note">Vaccinations for {selectedPets.filter(pet=>!isVaccinatedStatus(pet.vaccinationStatus)).map(pet=>pet.name).join(", ")} must be verified before the first programme session. You can book now and update it in My PawSpace; a Meet &amp; Greet needs no proof.</p>}</div>}</div>{!accountLoading&&!accountError&&dogs.length>0&&<fieldset className={styles.petList}><legend>What should training focus on? (optional)</legend>{goalOptions.map(goal=><button key={goal} type="button" aria-pressed={goals.includes(goal)} className={styles.choice} onClick={()=>setGoals(current=>current.includes(goal)?current.filter(item=>item!==goal):[...current,goal])}>{goal}</button>)}<label>Anything your trainer should know? (optional)<textarea value={behaviourNotes} maxLength={500} onChange={event=>setBehaviourNotes(event.target.value)} className={styles.input} placeholder="For example: pulls on the lead, nervous around other dogs"/></label></fieldset>}{(accountLoading||catalogueLoading)&&<p role="status">Loading your account and training plans before choosing a session…</p>}<label>First session date<input type="date" disabled={accountLoading||catalogueLoading} value={date} onChange={event=>setDate(event.target.value)} className={styles.input}/></label><label>First session time (IST)<input type="time" disabled={accountLoading||catalogueLoading} value={time} step={900} onChange={event=>setTime(event.target.value)} className={styles.input}/></label><label>Days between sessions<select value={cadenceDays} disabled={accountLoading||catalogueLoading||packageCode==="trainer-meet-greet"} onChange={event=>setCadenceDays(Number(event.target.value))}>{[1,2,3,4,5,6,7].map(value=><option key={value} value={value}>{value===7?"Every week":`Every ${value} day${value===1?"":"s"}`}</option>)}</select></label></div><section aria-label="Training service address"><strong>Service address</strong><p>{savedAddressText}</p><Link href={routeScope==="v2"?"/v2/account":"/mobile-app"}>Manage saved address</Link><p>The same saved doorstep is used for all sessions. Each session must fit the programme validity.</p></section>{locationLoading?<p>Confirming your training zone…</p>:locationError?<p role="alert">{locationError}</p>:location?<small>Training zone {location.zoneName} · confirmed from your address PIN code</small>:null}</section><section className={styles.card}><h2>2. Programme</h2>{catalogueLoading?<p>{routeScope==="v2"?"Loading training plans…":"Loading canonical Training catalogue…"}</p>:<>{Boolean(routeScope==="v2")?<TrainingFamilyChoices plans={packages} selectedCode={packageCode} recommendation={recommendation} petCount={petCount} renderChoice={item=><button key={item.package_code} onClick={()=>setPackageCode(item.package_code)} aria-pressed={packageCode===item.package_code} className={styles.choice}><strong>{item.name}</strong>{recommendation?.basis==="goals"&&recommendation.packageCode===item.package_code&&<small className={styles.block}>Best match for {recommendation.matchedGoals.join(" + ")}</small>}<div>{routeScope==="v2"?trainingSessionCount(item.sessions):`${item.sessions} session(s)`} · valid {item.validity_days} days</div><b>{money(trainingPriceForPets(item.base_price,Math.max(1,petCount),item.extra_pet_percent))}</b>{petCount>1&&<small className={styles.block}>for {petCount} dogs</small>}<small className={styles.block}>{item.meet_and_greet?(routeScope==="v2"?"Meet & Greet · paid in full":"Meet & Greet · prepaid"):(routeScope==="v2"?"Pay in full, or 50% now":"Programme · prepaid or approved split")}</small></button>}/>:<div className={styles.grid2}>{packages.map(item=><button key={item.package_code} onClick={()=>setPackageCode(item.package_code)} aria-pressed={packageCode===item.package_code} className={styles.choice}><strong>{item.name}</strong>{recommendation?.basis==="goals"&&recommendation.packageCode===item.package_code&&<small className={styles.block}>Best match for {recommendation.matchedGoals.join(" + ")}</small>}<div>{routeScope==="v2"?trainingSessionCount(item.sessions):`${item.sessions} session(s)`} · valid {item.validity_days} days</div><b>{money(trainingPriceForPets(item.base_price,Math.max(1,petCount),item.extra_pet_percent))}</b>{petCount>1&&<small className={styles.block}>for {petCount} dogs</small>}<small className={styles.block}>{item.meet_and_greet?(routeScope==="v2"?"Meet & Greet · paid in full":"Meet & Greet · prepaid"):(routeScope==="v2"?"Pay in full, or 50% now":"Programme · prepaid or approved split")}</small></button>)}</div>}</>}<div className={styles.topGap}><label>Payment mode <select value={paymentMode} disabled={packageCode==="trainer-meet-greet"} onChange={event=>setPaymentMode(event.target.value as "prepaid"|"split")}><option value="split">{routeScope==="v2"?"50% now, the rest before the final session":"Approved split"}</option><option value="prepaid">{routeScope==="v2"?"Pay in full":"Full prepaid"}</option></select></label></div></section><section className={styles.card}><h2>3. Available trainer</h2>{routeScope==="v2"&&<><button type="button" aria-pressed={providerSelection==="auto"} className={styles.choice} disabled={busy} onClick={()=>{setProviderSelection("auto");setError("");}}>PawSpace chooses the best available trainer</button><p>{providerSelection==="auto"?"PawSpace will match one eligible trainer for every session. The assigned trainer is confirmed before payment.":"Your specific trainer will not be replaced silently. Choose automatic matching to allow another eligible trainer."}</p>{providerSelection==="specific"&&!activeTrainer&&!availabilityLoading&&<p role="alert">Your chosen trainer is unavailable for this programme. Choose another trainer or automatic matching.</p>}</>}<p>Availability is checked for every session in this programme. A search does not reserve a trainer.</p><button type="button" disabled={!location||petCount===0||busy||availabilityLoading} onClick={()=>{setError("");setAvailabilityRefresh(value=>value+1);}}>Refresh trainer availability</button>{availabilityLoading?<p role="status">Checking availability for every programme session...</p>:!location?<p>Your training zone