now · ${money(currentQuote.totalAmount-currentQuote.amountDueNow)} before your final session`:`${money(currentQuote.amountDueNow)} due now`):`${money(currentQuote.amountDueNow)} sandbox amount due now · live money disabled`):locationError?"Booking unavailable for your location":locationLoading?"Confirming your training zone…":petCount===0?"Select at least one of your dogs to continue":"Repricing for your current selections…"}</small></div><Button data-v2-action={routeScope==="v2"?"primary":undefined} size="lg" disabled={!currentQuote||!activeTrainer||busy||!account||!location||petCount===0} onClick={()=>void confirm()}>{busy?"Reserving trainer…":"Reserve trainer & continue to payment →"}</Button></section></main>;
