 const refresh=async()=>{const fresh=await loadV2CustomerAccount();apply(fresh);};
 const save=async()=>{if(!account||busy)return;setError("");setMessage("");if(!name.trim()){setError("Your name is required.");return;}if(secondaryPhone&&!/^\d{10}$/.test(secondaryPhone)){setError("Alternate mobile must be 10 digits.");return;}const emailIssue=customerEmailIssue(email);if(emailIssue){setError(emailIssue);return;}setBusy(true);try{await updateV2CustomerProfile({name:name.trim(),primaryPhone:account.primaryPhone,secondaryPhone:secondaryPhone||null,email:email.trim()||null,cityId:account.cityId,idempotencyKey:"v2-profile-"+crypto.randomUUID()});await refresh();setMessage("Profile updated.");}catch(p){setError(p instanceof Error?p.message:"We could not update your account.");}finally{setBusy(false);}};
