 <section className={styles.card} style={{marginTop:16}}><h2>Pets</h2><p className={styles.muted}>Add or edit the same rich pet profiles used by booking, safety and care matching.</p><PetManager customer={{customerId:account.customerId,customerName:account.name,phone:account.primaryPhone}} onPetsChanged={pets=>setAccount(current=>current?{...current,pets}:current)}/></section>
 <section className={styles.card} style={{marginTop:16}}><h2>TEST coin preview</h2><p className={styles.muted}>Try demonstration rewards across your services in enabled test environments. TEST coins have no cash value and do not change your payments.</p><Link href="/v2/test-coins" className={styles.back}>Open TEST coin preview</Link><p><Link href="/v2/test-coin-wallet" className={styles.back}>View TEST wallet, lifetime activity and expiry</Link></p></section>
 <section className={styles.card} style={{marginTop:16}}><h2>Rewards, billing & privacy</h2><p className={styles.muted}>These are the same governed PawSpace account tools used by the V1 customer app.</p><ReferralCard customer={{customerId:account.customerId,customerName:account.name,phone:account.primaryPhone}}/><AccountTools customerId={account.customerId} onSupport={()=>window.location.assign("/v2/support")}/><div className={styles.actions}><button className={styles.back} type="button" onClick={()=>setShowNotifications(true)}>Notifications & reminders</button><Link href="/v2/support" className={styles.back}>Report an issue / support</Link></div>{showNotifications&&<CustomerNotifications customerId={account.customerId} onClose={()=>setShowNotifications(false)}/>}</section></>}</div>
