.page.page .heroArt>span { display:none; }
:global(html[data-paw-style="professional"]) .page.page .hero { display:block; }
:global(html[data-paw-style="professional"]) .page.page .heroArt { display:none; }
.page.page .layout { max-width:1100px; gap:16px; margin:0 auto; padding:0 16px 28px; }
.page.page .step { padding:16px; border-radius:var(--ds-radius-lg,18px); }
.page.page .stepHead { gap:9px; margin-bottom:12px; }.page.page .stepHead h2 { font-size:18px; line-height:1.3; margin:0; }
.page.page .stepHead small { font-size:10px !important; }.page.page .stepHead>span { width:30px; height:30px; }
.page.page .petCard,.page.page .providerCard { min-height:58px; padding:10px; gap:8px; }
.page.page .packageCard { min-height:0; padding:14px; border-radius:var(--ds-radius-md,14px); }
