.checkoutPage { composes:palette from "../../components/brand/brand-surface.module.css"; }
.checkoutPage.checkoutPage { background:radial-gradient(circle at 15% 0%,var(--brand-raised) 0,transparent 28%),radial-gradient(circle at 90% 20%,var(--brand-raised) 0,transparent 30%),var(--brand-bg); color:var(--brand-text); }
.checkoutPage .checkoutCard { background:var(--brand-surface); border-color:var(--brand-line); box-shadow:var(--brand-shadow); }
.checkoutPage .checkoutCard>p,.checkoutPage .checkoutFacts span,.checkoutPage .checkoutCard .safe p,.checkoutPage .confirmedBox small,.checkoutPage .recoveryForm p,.checkoutPage .checkoutActions p,.checkoutPage .receiptNote { color:var(--brand-muted); }
.checkoutPage .eyebrow { color:var(--brand-muted); background:var(--brand-raised); border:1px solid var(--brand-line); }
