.checkoutPage .recoveryForm input { border-color:var(--brand-line); background:var(--brand-surface); color:var(--brand-text); }

/* G10: real, keyboard-accessible step navigation on desktop and mobile. */
.page .stepNavigation { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:6px; min-width:0; }
.page .stepNavigation button { display:flex; align-items:center; justify-content:center; gap:6px; min-height:44px; border:1px solid var(--brand-line); border-radius:calc(12px * var(--paw-radius-scale)); padding:7px 10px; background:var(--brand-surface); color:var(--brand-text); font:inherit; font-size:12px; font-weight:700; cursor:pointer; }
