.page .stepNavigation button[aria-current="step"] { background:var(--brand-primary); color:var(--brand-on-primary); }
.page .stepNavigation button[aria-current="step"] b { background:var(--brand-gold); color:var(--brand-on-gold); }
.page .stepNavigation button:disabled { color:var(--brand-muted); cursor:not-allowed; opacity:.65; }
.page .step { scroll-margin-top:20px; }
.page .step:focus-visible { outline:3px solid var(--brand-gold); outline-offset:3px; }
