/* Compact V2 booking presentation. Pet, package, address, capacity and checkout controls remain intact. */
.page.page .nav { min-height:64px; height:auto; padding:10px max(14px,calc((100vw - 1100px)/2)); }
.page.page .brand img { width:90px; max-height:46px; object-fit:contain; }
.page.page .hero { min-height:0; margin:16px auto; max-width:1100px; padding:0 16px; grid-template-columns:minmax(0,1fr) 84px; gap:14px; align-items:center; }
.page.page .hero h1 { font-size:28px; line-height:1.15; margin:5px 0 8px; letter-spacing:-.02em; }
.page.page .hero h1 br { display:none; }
.page.page .hero p { margin:0; font-size:13px; line-height:1.5; color:var(--brand-muted) !important; }
.page.page .hero .eyebrow { padding:3px 7px; font-size:11px !important; }
.page.page .heroArt { min-height:0; height:84px; width:84px; border-radius:calc(20px * var(--paw-radius-scale)); }
.page.page .heroArt img { width:100%; height:100%; object-fit:cover; }
.page.page .heroArt>span { display:none; }
:global(html[data-paw-style="professional"]) .page.page .hero { display:block; }
:global(html[data-paw-style="professional"]) .page.page .heroArt { display:none; }
.page.page .layout { max-width:1100px; gap:16px; margin:0 auto; padding:0 16px 28px; }
.page.page .step { padding:16px; border-radius:var(--ds-radius-lg,18px); }
.page.page .stepHead { gap:9px; margin-bottom:12px; }.page.page .stepHead h2 { font-size:18px; line-height:1.3; margin:0; }
.page.page .stepHead small { font-size:10px !important; }.page.page .stepHead>span { width:30px; height:30px; }
.page.page .petCard,.page.page .providerCard { min-height:58px; padding:10px; gap:8px; }
.page.page .packageCard { min-height:0; padding:14px; border-radius:var(--ds-radius-md,14px); }
.page.page .packageCard h3 { font-size:17px; margin:6px 0; }.page.page .packageCard p { font-size:13px; line-height:1.4; margin:5px 0; }
.page.page .summary { border-radius:var(--ds-radius-lg,18px); padding:18px; }
@media(max-width:640px) { .page.page .hero { margin:12px auto; }.page.page .hero h1 { font-size:23px; }.page.page .layout { display:flex; flex-direction:column; padding-inline:12px; }.page.page .petGrid { grid-template-columns:1fr; gap:8px; }.page.page .packageGrid { gap:8px; }.page.page .summary { position:static; width:auto; }.page.page .progress { display:none; } }

/* Checkout and doorstep recovery render their own root <main>, never inside .page, so the pairings above cannot reach them.
   Same palette and pairings, scoped to that root. Presentation only: the panel, its reads and payment actions are unchanged. */
.checkoutPage { composes:palette from "../../components/brand/brand-surface.module.css"; }
.checkoutPage.checkoutPage { background:radial-gradient(circle at 15% 0%,var(--brand-raised) 0,transparent 28%),radial-gradient(circle at 90% 20%,var(--brand-raised) 0,transparent 30%),var(--brand-bg); color:var(--brand-text); }
.checkoutPage .checkoutCard { background:var(--brand-surface); border-color:var(--brand-line); box-shadow:var(--brand-shadow); }
.checkoutPage .checkoutCard>p,.checkoutPage .checkoutFacts span,.checkoutPage .checkoutCard .safe p,.checkoutPage .confirmedBox small,.checkoutPage .recoveryForm p,.checkoutPage .checkoutActions p,.checkoutPage .receiptNote { color:var(--brand-muted); }
.checkoutPage .eyebrow { color:var(--brand-muted); background:var(--brand-raised); border:1px solid var(--brand-line); }
.checkoutPage .checkoutFacts div,.checkoutPage .checkoutCard .safe,.checkoutPage .confirmedBox { background:var(--brand-raised); border:1px solid var(--brand-line); }
.checkoutPage .checkoutCard .safe b { color:var(--brand-text); }
.checkoutPage .checkoutCard .safe>span { color:var(--brand-warning); }
.checkoutPage .confirmedBox>span,.checkoutPage .doneLink { background:var(--brand-primary); color:var(--brand-on-primary); }
.checkoutPage .statusButton { border:1px solid var(--brand-line); background:var(--brand-surface); color:var(--brand-text); }
.checkoutPage .continue { background:var(--brand-gold); color:var(--brand-on-gold); }
.checkoutPage .checkoutCard .inlineError { background:var(--brand-danger-bg); color:var(--brand-danger); border:1px solid var(--brand-line); }
.checkoutPage .recoveryForm input { border-color:var(--brand-line); background:var(--brand-surface); color:var(--brand-text); }

/* G10: real, keyboard-accessible step navigation on desktop and mobile. */
.page .stepNavigation { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:6px; min-width:0; }
.page .stepNavigation button { display:flex; align-items:center; justify-content:center; gap:6px; min-height:44px; border:1px solid var(--brand-line); border-radius:calc(12px * var(--paw-radius-scale)); padding:7px 10px; background:var(--brand-surface); color:var(--brand-text); font:inherit; font-size:12px; font-weight:700; cursor:pointer; }
.page .stepNavigation button b { display:grid; place-items:center; width:22px; height:22px; flex:none; border-radius:50%; background:var(--brand-raised); }
.page .stepNavigation button[aria-current="step"] { background:var(--brand-primary); color:var(--brand-on-primary); }
.page .stepNavigation button[aria-current="step"] b { background:var(--brand-gold); color:var(--brand-on-gold); }
.page .stepNavigation button:disabled { color:var(--brand-muted); cursor:not-allowed; opacity:.65; }
.page .step { scroll-margin-top:20px; }
.page .step:focus-visible { outline:3px solid var(--brand-gold); outline-offset:3px; }
@media(max-width:900px) {
  .page.page .nav { grid-template-columns:minmax(0,1fr) auto; gap:10px; padding:10px 0; }
  .page .stepNavigation { grid-column:1 / -1; grid-row:2; width:100%; }
  .page.page .close { grid-column:2; grid-row:1; }
  .page .stepNavigation button { flex-direction:column; gap:3px; padding:6px 3px; font-size:11px; }
}

/* Keep the horizontal date strip inside the booking column, not the page's hidden overflow. */
.page .journey { width:100%; max-width:100%; min-width:0; box-sizing:border-box; }
.page .journey > .step { min-width:0; max-width:100%; box-sizing:border-box; }

/* Customer/partner visual audit UI-05: summary text must remain readable on the dark brand summary card. */
.page .summary .summaryTop span,
.page .summary .summaryPet small,
.page .summary .summaryRows span,
.page .summary .priceBlock > span,
.page .summary .priceBlock small,
.page .summary .safe p {
  color:var(--brand-on-primary) !important;
}
.page .summary .summaryTop b,
.page .summary .priceBlock > b,
.page .summary .safe > span {
  color:var(--brand-gold) !important;
}

/* Signature/Coral primary fills are too light for gold summary accents; use the dark brand surface. */
.page .summary {
  background:var(--brand-hero) !important;
}

/* Summary labels sit on brand-primary, so use its foreground rather than light-surface accents. */
.page.page .summary :is(.summaryTop span, .summaryTop b, .summaryPet small, .summaryRows span,
  .priceBlock > span, .priceBlock > b, .priceBlock small) { color:var(--brand-on-primary) !important; }

/* Premium Grooming phase 1: existing four-step flow, presentation only. */
.page.page { padding-inline:clamp(12px,3vw,32px); }
.page.page .nav { max-width:1100px; padding:16px 0; gap:20px; grid-template-columns:minmax(100px,1fr) minmax(0,600px) auto; }
.page.page .brand img { width:112px; max-height:48px; }
.page.page .hero { margin:28px auto; padding:0; gap:24px; }
.page.page .hero h1 { font-size:clamp(28px,3.5vw,40px); line-height:1.15; letter-spacing:-.025em; margin:10px 0; }
.page.page .hero p { font-size:15px; line-height:1.65; max-width:720px; }
.page.page .hero .eyebrow { padding:6px 10px; letter-spacing:.1em; }
.page.page .layout { padding:0 0 32px; gap:24px; grid-template-columns:minmax(0,1fr) 350px; }
.page.page .journey { gap:24px; }
.page.page .step { padding:24px; background:var(--brand-surface) !important; border:1px solid var(--brand-line); border-radius:var(--paw-card-radius); box-shadow:var(--brand-shadow); backdrop-filter:none; }
.page.page .stepHead { gap:12px; margin-bottom:20px; align-items:center; }
.page.page .stepHead > span { width:36px; height:36px; flex:none; border-radius:var(--paw-control-radius); }
.page.page .stepHead h2 { font-size:22px; line-height:1.35; letter-spacing:-.02em; }
.page.page .stepHead small { font-size:11px !important; line-height:1.5; letter-spacing:.12em; }
.page.page .stepNavigation { gap:8px; }
.page.page .stepNavigation button { min-height:48px; padding:10px 8px; line-height:1.35; font-size:13px; border-radius:var(--paw-control-radius); }
.page.page .stepNavigation button span { overflow-wrap:anywhere; }
.page.page .stepNavigation button:disabled { opacity:1; border-style:dashed; }
.page.page .stepNavigation button[aria-current="step"] { box-shadow:0 0 0 2px var(--brand-surface),0 0 0 3px var(--brand-primary); }
.page.page .petCard,.page.page .providerCard { min-height:76px; padding:16px; gap:12px; border-radius:var(--paw-control-radius); }
.page.page .petCard div,.page.page .providerCard div { overflow-wrap:anywhere; }
.page.page .packageGrid,.page.page .petGrid,.page.page .providerGrid { gap:12px; }
.page.page .packageCard { padding:20px; border-radius:var(--paw-card-radius); }
