.page.page .journey .addressBox { gap:12px; grid-template-columns:minmax(0,1fr) 120px; }
.page.page .journey .addressBox > button { grid-column:1 / -1; min-height:52px; }
.page.page .journey .addressBox label { min-width:0; font-size:13px; line-height:1.5; }
.page.page .journey .addressBox input { width:100%; min-width:0; box-sizing:border-box; }
.page.page .helper { line-height:1.6; margin-top:12px; }
