.page {
  --emerald: var(--ui-brand-deep);
  --emerald-deep: var(--ui-brand-deep);
  --emerald-soft: var(--ui-brand-deep);
  --gold: var(--ui-gold-soft);
  --ink: var(--ui-ink);
  --muted: var(--ui-muted);
  --cream: var(--ui-canvas);
  --paper: var(--ui-surface);
  --line: color-mix(in srgb, var(--ui-brand-deep) 10%, transparent);
  min-height: 100vh;
  color: var(--ink);
  background:
    radial-gradient(circle at 12% 0%, color-mix(in srgb, var(--ui-gold-soft) 11%, transparent), transparent 28%),
    radial-gradient(circle at 90% 8%, color-mix(in srgb, var(--ui-brand-deep) 10%, transparent), transparent 30%),
    var(--ui-canvas);
  font-family: var(--paw-font);
  position: relative;
  overflow-x: hidden;
}

.page * { box-sizing: border-box; }
.page a { color: inherit; text-decoration: none; }
.page button, .page input { font: inherit; }
.page button { color: inherit; }
.aurora { position: fixed; inset: 0; pointer-events: none; opacity: .75; background: linear-gradient(115deg, transparent 0 72%, color-mix(in srgb, var(--ui-surface) 32%, transparent)); }
.shell { width: min(1420px, calc(100% - 56px)); margin: 0 auto; position: relative; z-index: 1; }

.nav { height: 86px; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 24px; border-bottom: 1px solid var(--line); }
.logoLink { width: fit-content; display: inline-flex; align-items: center; }
.logo { width: 168px; max-height: 46px; object-fit: contain; object-position: left center; mix-blend-mode: multiply; }
.navCenter { justify-self: center; display: flex; align-items: center; gap: 10px; padding: 11px 16px; background: color-mix(in srgb, var(--ui-surface) 62%, transparent); border: 1px solid color-mix(in srgb, var(--ui-brand-deep) 8%, transparent); border-radius: 999px; font-size: 12px; font-weight: 760; color: var(--paw-link); backdrop-filter: blur(16px); }
.locationDot { width: 8px; height: 8px; border-radius: 50%; background: var(--ui-brand-primary); box-shadow: 0 0 0 4px rgba(45,150,111,.12); }
.navDivider { width: 1px; height: 14px; background: color-mix(in srgb, var(--ui-brand-deep) 15%, transparent); }
.navActions { justify-self: end; display: flex; align-items: center; gap: 10px; }
.aiNav, .signIn { height: 44px; border-radius: var(--paw-card-radius); padding: 0 16px; display: inline-flex; align-items: center; gap: 8px; border: 1px solid color-mix(in srgb, var(--ui-brand-deep) 10%, transparent); background: color-mix(in srgb, var(--ui-surface) 72%, transparent); font-size: 12px; font-weight: 850; box-shadow: 0 6px 24px rgba(23,52,44,.05); }
.aiNav span { color: var(--ui-gold-ink); }
.signIn { border: 0; background: var(--emerald); color: var(--ui-on-primary); cursor: pointer; padding-inline: 20px; }
.profileButton { border: 0; background: transparent; display: flex; align-items: center; gap: 9px; cursor: pointer; padding: 4px; border-radius: var(--paw-card-radius); }
.profileButton:hover { background: color-mix(in srgb, var(--ui-surface) 58%, transparent); }
.avatar { width: 36px; height: 36px; display: grid; place-items: center; border-radius: calc(12px * var(--paw-radius-scale)); background: var(--emerald); color: #fff; font-weight: 900; box-shadow: inset 0 0 0 1px rgba(255,255,255,.16); }
.profileText { display: grid; text-align: left; line-height: 1.05; }
.profileText small { font-size: 9px; color: var(--ui-muted); text-transform: uppercase; letter-spacing: .08em; }
.profileText b { font-size: 12px; margin-top: 4px; }

.hero { margin-top: 28px; min-height: 590px; border-radius: 42px; overflow: hidden; display: grid; grid-template-columns: 1.08fr .92fr; background:
  radial-gradient(circle at 15% 20%, color-mix(in srgb, var(--ui-brand-primary) 26%, transparent), transparent 24%),
  radial-gradient(circle at 74% 18%, color-mix(in srgb, var(--ui-gold-soft) 18%, transparent), transparent 25%),
  linear-gradient(135deg, var(--ui-brand-deep) 0%, var(--ui-brand-deep) 58%, var(--ui-brand-deep) 100%);
  color: var(--ui-on-primary); box-shadow: 0 34px 88px rgba(5,46,37,.22); position: relative; isolation: isolate; }
.hero::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(90deg, color-mix(in srgb, var(--ui-surface) 3.5%, transparent) 1px, transparent 1px), linear-gradient(color-mix(in srgb, var(--ui-surface) 3.5%, transparent) 1px, transparent 1px); background-size: 72px 72px; mask-image: linear-gradient(to right, var(--ui-primary), transparent 78%); }
.heroCopy { padding: clamp(48px, 6vw, 86px); display: flex; flex-direction: column; justify-content: center; position: relative; z-index: 2; }
.kicker { width: fit-content; display: inline-flex; align-items: center; gap: 9px; border: 1px solid color-mix(in srgb, var(--ui-surface) 16%, transparent); background: color-mix(in srgb, var(--ui-surface) 6%, transparent); padding: 9px 13px; border-radius: 999px; font-size: 10px; font-weight: 850; letter-spacing: .13em; color: var(--ui-on-primary); }
.kicker i { width: 7px; height: 7px; background: var(--gold); border-radius: 50%; box-shadow: 0 0 0 5px rgba(231,178,76,.13); }
.hero h1 { margin: 26px 0 18px; font-size: clamp(48px, 5.1vw, 78px); line-height: .98; letter-spacing: -.055em; max-width: 820px; font-weight: 840; }
.hero h1 em { color: var(--ui-soft-ink); font-style: normal; font-weight: 560; }
.heroCopy > p { margin: 0; max-width: 610px; color: var(--ui-on-primary); font-size: clamp(16px, 1.5vw, 20px); line-height: 1.55; }
.heroActions { margin-top: 34px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.primaryAction, .secondaryAction { min-height: 54px; padding: 0 19px; border-radius: var(--paw-card-radius); display: inline-flex; align-items: center; justify-content: center; gap: 13px; font-size: 13px; font-weight: 900; }
.primaryAction { background: var(--gold); color: var(--ui-on-gold) !important; box-shadow: 0 12px 34px rgba(231,178,76,.2); }
.primaryAction span { font-size: 17px; }
.secondaryAction { color: var(--ui-on-primary) !important; border: 1px solid color-mix(in srgb, var(--ui-surface) 18%, transparent); background: color-mix(in srgb, var(--ui-surface) 7%, transparent); backdrop-filter: blur(10px); }
.secondaryAction span { color: var(--ui-soft-ink); }
.trustRow { display: flex; gap: 28px; margin-top: 44px; padding-top: 24px; border-top: 1px solid color-mix(in srgb, var(--ui-surface) 11%, transparent); width: fit-content; }
.trustRow span { display: grid; gap: 3px; }
.trustRow b { font-size: 22px; letter-spacing: -.04em; }
.trustRow small { color: var(--ui-soft-ink); font-size: 10px; font-weight: 700; }

.heroVisual { min-height: 590px; position: relative; display: grid; place-items: center; padding: 44px 50px 40px 10px; z-index: 1; }
.heroHalo { position: absolute; width: 540px; height: 540px; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, var(--ui-gold-soft) 29%, transparent) 0 1%, color-mix(in srgb, var(--ui-gold-soft) 13%, transparent) 28%, transparent 67%); filter: blur(2px); }
.petPortrait { width: min(480px, 92%); aspect-ratio: .88; border-radius: 46% 46% 38% 38% / 38% 38% 28% 28%; overflow: hidden; position: relative; transform: translateY(18px); background: var(--ui-line); box-shadow: 0 45px 75px rgba(0,0,0,.22), inset 0 0 0 1px rgba(255,255,255,.22); }
.petPortrait::after { content: ""; position: absolute; inset: 0; box-shadow: inset 0 -100px 80px rgba(3,39,31,.17); }
.petPortrait img { width: 100%; height: 100%; object-fit: cover; display: block; transform: scale(1.03); }
.floatingCardTop, .floatingCardBottom { position: absolute; display: flex; align-items: center; gap: 12px; background: color-mix(in srgb, var(--ui-surface) 93%, transparent); color: var(--ui-ink); padding: 14px 17px; border-radius: var(--paw-card-radius); box-shadow: 0 18px 48px rgba(1,27,22,.21); backdrop-filter: blur(16px); z-index: 3; max-width: 260px; }
.floatingCardTop { top: 88px; right: 18px; }
.floatingCardBottom { left: 18px; bottom: 68px; }
.floatingCardTop div, .floatingCardBottom div { display: grid; gap: 2px; }
.floatingCardTop small, .floatingCardBottom small { font-size: 8px; letter-spacing: .12em; color: var(--ui-muted); font-weight: 900; }
.floatingCardTop b, .floatingCardBottom b { font-size: 11px; line-height: 1.35; }
.liveDot { width: 10px; height: 10px; border-radius: 50%; background: var(--ui-brand-primary); box-shadow: 0 0 0 5px rgba(51,165,121,.13); flex: 0 0 auto; }
.spark { width: 30px; height: 30px; display: grid; place-items: center; border-radius: calc(10px * var(--paw-radius-scale)); background: var(--ui-gold-wash); color: var(--ui-gold-ink); font-weight: 900; }

.notice { margin-top: 18px; background: var(--ui-gold-wash); border: 1px solid var(--ui-gold-line); border-radius: var(--paw-card-radius); min-height: 64px; padding: 12px 14px; display: flex; align-items: center; gap: 12px; color: var(--ui-ink); }
.notice > span { color: var(--ui-gold-ink); }
.notice div { flex: 1; }
.notice b { font-size: 11px; }
.notice p { margin: 2px 0 0; font-size: 11px; color: var(--ui-gold-ink); }
.notice button { border: 0; border-radius: calc(11px * var(--paw-radius-scale)); padding: 9px 12px; background: var(--ui-gold-soft); cursor: pointer; font-weight: 800; font-size: 11px; }

.familyStrip { margin-top: 22px; min-height: 108px; border-radius: var(--paw-card-radius); border: 1px solid var(--line); background: color-mix(in srgb, var(--ui-surface) 69%, transparent); box-shadow: 0 10px 38px rgba(27,54,46,.05); display: grid; grid-template-columns: minmax(260px, 1fr) auto; align-items: center; gap: 24px; padding: 20px 22px 20px 28px; backdrop-filter: blur(16px); }
.sectionTitleCompact { display: grid; gap: 5px; }
.sectionTitleCompact span { font-size: 9px; letter-spacing: .13em; font-weight: 900; color: var(--ui-muted); text-transform: uppercase; }
