.familyFacts { display: flex; align-items: stretch; gap: 10px; }
.fact { min-width: 128px; padding: 11px 14px; border-radius: var(--paw-card-radius); background: var(--ui-canvas); display: flex; align-items: center; gap: 10px; }
.fact > span { width: 31px; height: 31px; border-radius: calc(10px * var(--paw-radius-scale)); display: grid; place-items: center; background: var(--ui-canvas); color: var(--ui-ink); font-size: 13px; }
.fact div { display: grid; }
.fact b { font-size: 16px; }
.fact small { font-size: 9px; color: var(--ui-muted); }
.familySignIn { border: 0; background: var(--emerald); color: #fff; min-width: min(510px, 48vw); min-height: 66px; border-radius: var(--paw-card-radius); display: grid; grid-template-columns: auto 1fr auto; gap: 13px; align-items: center; text-align: left; padding: 11px 17px; cursor: pointer; box-shadow: 0 14px 34px rgba(6,47,39,.14); }
.familySignIn > span { width: 38px; height: 38px; border-radius: calc(13px * var(--paw-radius-scale)); display: grid; place-items: center; color: var(--ui-on-gold); background: var(--gold); font-size: 18px; }
.familySignIn div { display: grid; gap: 2px; }
.familySignIn b { font-size: 12px; }
.familySignIn small { color: var(--ui-soft-ink); font-size: 10px; }
.familySignIn strong { font-size: 11px; color: var(--ui-soft-ink); }

.contentGrid { display: grid; grid-template-columns: minmax(0, 1.72fr) minmax(315px, .68fr); gap: 22px; align-items: start; margin: 54px 0 0; }
.sectionHeader { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 19px; padding: 0 3px; }
.eyebrow { font-size: 9px; letter-spacing: .14em; color: var(--ui-muted); font-weight: 900; }
.sectionHeader h2 { margin: 7px 0 0; font-size: clamp(28px, 3vw, 41px); letter-spacing: -.045em; line-height: 1.04; }
.sectionHeader > p { max-width: 260px; text-align: right; margin: 0; color: var(--ui-muted); line-height: 1.5; font-size: 11px; }
.servicesGrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 13px; }
.serviceCard { --accent: var(--ui-gold-soft); --wash: var(--ui-gold-wash); min-height: 220px; border-radius: var(--paw-card-radius); padding: 22px; position: relative; overflow: hidden; isolation: isolate; background: linear-gradient(135deg, var(--ui-surface) 0 54%, var(--wash) 100%); border: 1px solid color-mix(in srgb, var(--ui-brand-deep) 9%, transparent); box-shadow: 0 10px 34px rgba(21,49,41,.055); display: block; transition: transform .28s ease, box-shadow .28s ease, border-color .28s ease; }
.serviceCard::after { content: ""; position: absolute; width: 170px; height: 170px; border-radius: 50%; right: -64px; bottom: -75px; background: var(--accent); opacity: .09; z-index: -1; }
.serviceCard:hover { transform: translateY(-4px); box-shadow: 0 20px 48px rgba(21,49,41,.1); border-color: color-mix(in srgb, var(--accent) 28%, transparent); }
.serviceHero { min-height: 280px; grid-column: span 2; background: linear-gradient(118deg, var(--ui-surface) 0 54%, var(--wash) 54% 100%); }
.serviceHero .serviceArt { width: 42%; right: 7%; bottom: -5%; }
.serviceHero .serviceCopy { max-width: 48%; }
.serviceCopy { position: relative; z-index: 2; max-width: 64%; }
.serviceCopy > span { font-size: 9px; text-transform: uppercase; letter-spacing: .12em; font-weight: 900; color: color-mix(in srgb, var(--accent) 75%, var(--ui-ink)); }
.serviceCopy h3 { margin: 8px 0 6px; font-size: 24px; letter-spacing: -.035em; }
.serviceCopy p { margin: 0; color: var(--ui-muted); font-size: 11px; line-height: 1.5; }
.serviceState { display: inline-flex; margin-top: 22px; padding: 7px 9px; border-radius: calc(10px * var(--paw-radius-scale)); background: color-mix(in srgb, var(--ui-surface) 67%, transparent); color: var(--paw-link); font-size: 9px; font-weight: 850; }
.serviceArt { position: absolute; right: -9px; bottom: -14px; width: 47%; height: 92%; display: flex; align-items: end; justify-content: end; z-index: 1; }
.serviceArt img { max-width: 100%; max-height: 100%; object-fit: contain; filter: drop-shadow(0 16px 20px rgba(50,45,32,.09)); }
.serviceArrow { position: absolute; top: 17px; right: 17px; width: 31px; height: 31px; border-radius: calc(12px * var(--paw-radius-scale)); display: grid; place-items: center; background: color-mix(in srgb, var(--ui-surface) 82%, transparent); color: var(--ui-ink); font-size: 13px; z-index: 4; }
.serviceDisabled { filter: saturate(.68); cursor: not-allowed; }
.serviceDisabled:hover { transform: none; box-shadow: 0 10px 34px rgba(21,49,41,.055); }
.serviceDisabled .serviceArrow { opacity: .35; }

.rail { display: grid; gap: 13px; position: sticky; top: 18px; }
.aiCard, .bookingCard, .promiseCard { border-radius: var(--paw-card-radius); overflow: hidden; }
.aiCard { min-height: 380px; background: linear-gradient(145deg, var(--ui-brand-deep), var(--ui-brand-deep)); color: var(--ui-on-primary); padding: 24px; position: relative; box-shadow: 0 18px 50px rgba(6,47,39,.14); }
.aiCard::before { content: ""; position: absolute; width: 230px; height: 230px; border-radius: 50%; right: -92px; top: 66px; background: radial-gradient(circle, color-mix(in srgb, var(--ui-gold-soft) 32%, transparent), transparent 67%); }
.aiTop { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; position: relative; z-index: 1; }
.aiOrb { width: 42px; height: 42px; border-radius: var(--paw-card-radius); display: grid; place-items: center; background: var(--ui-gold-soft); color: var(--ui-on-gold); font-weight: 900; box-shadow: 0 10px 30px rgba(240,189,88,.17); }
.aiTop div { display: grid; gap: 2px; }
.aiTop small { color: var(--ui-soft-ink); font-size: 8px; font-weight: 900; letter-spacing: .12em; }
.aiTop b { font-size: 11px; }
.beta { padding: 6px 8px; border: 1px solid color-mix(in srgb, var(--ui-surface) 16%, transparent); border-radius: calc(9px * var(--paw-radius-scale)); font-size: 8px; font-weight: 900; color: var(--ui-soft-ink); }
.aiCard h3 { position: relative; z-index: 1; margin: 28px 0 11px; font-size: 29px; line-height: 1.04; letter-spacing: -.045em; }
.aiCard > p { position: relative; z-index: 1; color: var(--ui-soft-ink); line-height: 1.58; font-size: 11px; margin: 0; }
.aiCta { position: relative; z-index: 1; display: flex; justify-content: space-between; align-items: center; margin-top: 22px; background: var(--ui-gold-soft); color: var(--ui-on-gold) !important; min-height: 46px; border-radius: var(--paw-card-radius); padding: 0 13px; font-size: 11px; font-weight: 900; }
.promptChips { position: relative; z-index: 1; display: flex; flex-wrap: wrap; gap: 6px; margin-top: 13px; }
.promptChips span { padding: 6px 8px; background: color-mix(in srgb, var(--ui-surface) 7%, transparent); border: 1px solid color-mix(in srgb, var(--ui-surface) 9%, transparent); border-radius: calc(9px * var(--paw-radius-scale)); color: var(--ui-soft-ink); font-size: 8px; }
.bookingCard { background: color-mix(in srgb, var(--ui-surface) 78%, transparent); border: 1px solid var(--line); padding: 21px; box-shadow: 0 10px 35px rgba(24,52,44,.05); }
.cardLabel { display: flex; gap: 7px; align-items: center; font-size: 8px; letter-spacing: .12em; color: var(--ui-muted); font-weight: 900; }
.bookingCard h3 { margin: 16px 0 6px; font-size: 20px; letter-spacing: -.035em; }
.bookingCard > p { margin: 0; color: var(--ui-muted); font-size: 10px; line-height: 1.45; }
.bookingMeta { margin-top: 16px; display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.bookingMeta span { text-transform: capitalize; font-size: 9px; color: var(--ui-muted); }
.bookingMeta b { font-size: 12px; }
.statusPill { width: fit-content; margin-top: 12px; border-radius: 999px; padding: 7px 10px; background: #e7f0eb; color: #1b604b; font-size: 8px; text-transform: uppercase; letter-spacing: .08em; font-weight: 900; }
.textLink { display: inline-flex; margin-top: 15px; font-size: 10px; font-weight: 900; color: var(--ui-ink) !important; }
.promiseCard { background: var(--ui-line); padding: 16px 17px; display: flex; align-items: center; gap: 11px; }
.promiseMark { width: 38px; height: 38px; border-radius: calc(13px * var(--paw-radius-scale)); display: grid; place-items: center; flex: 0 0 auto; background: var(--emerald); color: var(--gold); font-size: 9px; font-weight: 950; letter-spacing: .08em; }
