.modalClose { position: absolute; top: 16px; right: 16px; border: 0; width: 34px; height: 34px; border-radius: calc(12px * var(--paw-radius-scale)); background: var(--ui-canvas); cursor: pointer; font-size: 20px; line-height: 1; }
