.field > input, .phoneField { width: 100%; min-height: 54px; border-radius: var(--paw-card-radius); border: 1px solid color-mix(in srgb, var(--ui-brand-deep) 13%, transparent); background: var(--ui-surface); outline: none; transition: border-color .18s, box-shadow .18s; }
