.codeInput { font-size: 24px !important; letter-spacing: .38em; text-align: center; font-weight: 800; }
.authPrimary { margin-top: 15px; width: 100%; min-height: 54px; border: 0; border-radius: var(--paw-card-radius); background: var(--emerald); color: #fff !important; cursor: pointer; display: flex; align-items: center; justify-content: space-between; padding: 0 17px; font-size: 11px; font-weight: 900; box-shadow: 0 12px 28px rgba(6,47,39,.15); }
