  .floatingCardTop, .floatingCardBottom { padding: 10px 12px; border-radius: var(--paw-card-radius); max-width: 205px; }
  .floatingCardTop { top: 18px; right: 9px; }
  .floatingCardBottom { left: 9px; bottom: 24px; }
  .floatingCardTop b, .floatingCardBottom b { font-size: 9px; }
  .familyFacts { gap: 7px; }
  .fact { min-width: 110px !important; }
  .familySignIn { grid-template-columns: auto 1fr; }
  .familySignIn strong { display: none; }
  .sectionHeader { align-items: start; }
  .sectionHeader > p { display: none; }
  .servicesGrid { grid-template-columns: 1fr; }
  .serviceCard, .serviceHero { grid-column: auto; min-height: 205px; }
  .serviceHero { min-height: 235px; background: linear-gradient(135deg, var(--ui-surface) 0 50%, var(--wash) 100%); }
  .serviceHero .serviceCopy { max-width: 62%; }
