  .footer { display: none; }
  .authModal { padding: 25px 20px 22px; border-radius: var(--paw-card-radius); }
  .authModal h2 { font-size: 28px; }
}

@media (prefers-reduced-motion: reduce) {
  .serviceCard, .authModal { transition: none; animation: none; }
}

